import itertools

def get_all_matchings(n):
    def find_matchings(remaining_nodes):
        if not remaining_nodes:
            return [[]]
        first = min(remaining_nodes)
        res = []
        for second in remaining_nodes:
            if first != second:
                for rest in find_matchings(remaining_nodes - {first, second}):
                    res.append([(first, second)] + rest)
        return res
    return find_matchings(set(range(n)))

def solve_small_n(n):
    matchings = get_all_matchings(n)
    matchings_sets = [set(tuple(sorted(pair)) for pair in m) for m in matchings]
    num_matchings = len(matchings_sets)

    for a in range(1, n):
        # Try all combinations of a matchings
        for indices in itertools.combinations(range(num_matchings), a):
            selected = [matchings_sets[i] for i in indices]
            # Check if they are disjoint
            disjoint = True
            union_pairs = set()
            for m_set in selected:
                if not m_set.isdisjoint(union_pairs):
                    disjoint = False
                    break
                union_pairs.update(m_set)

            if disjoint:
                # Check if they hit all matchings
                hits_all = True
                for m_set in matchings_sets:
                    if not (m_set & union_pairs):
                        hits_all = False
                        break
                if hits_all:
                    return a
    return n

