def check_k(k, n=40):
    for s in range(1, n // 2 + 1):
        c_min = s + 1
        if (c_min % 2) != ((n - s) % 2):
            c_min += 1

        if c_min > n - s:
            continue

        m = max(1, k - s + 1)
        if m % 2 == 0:
            m += 1

        if c_min * m <= n - s:
            n1 = (n-s) - (c_min-1) * m
            if n1 >= m and n1 % 2 == 1:
                sum_ni_ni_minus_1 = n1*(n1-1) + (c_min-1) * m*(m-1)
                if k * (n - 2*s) <= sum_ni_ni_minus_1:
                    return True
    return False

