def solve_for_n(n):
    for d in range(n // 2, 0, -1):
        for s in range(1, n):
            # Smallest odd |C_i| such that |C_i| >= d - s + 1
            m = d - s + 1
            if m <= 1:
                min_ci = 1
            else:
                min_ci = m if m % 2 == 1 else m + 1

            # We need k components of size at least min_ci.
            # So k * min_ci + s <= n.
            # Also k > s and k + s = n (mod 2).
            # We want to know if there exists such a k.

            # The smallest k is s + 1.
            # If (s + 1) + s is not n (mod 2), then the smallest k is s + 2.
            k = s + 1
            if (k + s) % 2 != n % 2:
                k += 1

            if k > s and k * min_ci + s <= n:
                return d
    return None

