def solve():
    n = 40
    # Precompute the possible values for a
    # We want to find the smallest a.
    for a in range(1, n):
        target_edges = a * (n // 2)
        for s in range(0, n + 1, 2):
            for k in range(s + 2, n - s + 1, 2):
                S = n - s
                Q = (S**2) - 2 * target_edges
                if Q < 0: continue

                if (S - k) % 2 == 0 and (Q - 2*S + k) % 4 == 0:
                    target_sum_x = (S - k) // 2
                    target_sum_x2 = (Q - 2*S + k) // 4

                    max_ni = (n - s) // 2
                    if max_ni % 2 == 0: max_ni -= 1
                    limit = (max_ni - 1) // 2

                    # DP to check if target_sum_x and target_sum_x2 are possible
                    # with k integers in [0, limit].
                    # dp[i][sx] = set of possible sx2
                    dp = [[set() for _ in range(target_sum_x + 1)] for _ in range(k + 1)]
                    dp[0][0].add(0)

                    for x in range(limit + 1):
                        for i in range(1, k + 1):
                            for sx in range(x, target_sum_x + 1):
                                for prev_sx2 in dp[i-1][sx-x]:
                                    if prev_sx2 + x*x <= target_sum_x2:
                                        dp[i][sx].add(prev_sx2 + x*x)

                    if target_sum_x2 in dp[k][target_sum_x]:
                        return a
    return None

