                    max_ni = (n - s) // 2
                    if max_ni % 2 == 0: max_ni -= 1
                    limit = (max_ni - 1) // 2
                    if limit < 0: continue

                    # Use a more efficient DP
                    # dp[i][sx] is a bitset of possible sx2
                    # Since target_sum_x2 <= 400, we can use a large integer as a bitset
                    dp = [[0] * (target_sum_x + 1) for _ in range(k + 1)]
                    dp[0][0] = 1

                    for x in range(limit + 1):
                        x2 = x*x
                        for i in range(1, k + 1):
                            for sx in range(x, target_sum_x + 1):
                                dp[i][sx] |= (dp[i-1][sx-x] << x2)

                    if (dp[k][target_sum_x] >> target_sum_x2) & 1:
                        return a
    return None

