def check_a(a, n=40):
    # Check if there exist s, k such that:
    # 1. k >= s + 2
    # 2. k = s mod 2 (since n is even, k = n-s mod 2 => k = s mod 2)
    # 3. k <= n-s
    # 4. k * n_min <= n-s where n_min is the smallest odd integer >= n-a-s
    #    Wait, n_min is the smallest odd integer >= m = n-a-s.
    #    If m <= 0, n_min = 1.

    for s in range(n + 1):
        for k in range(s + 2, n - s + 1, 2):
            m = n - a - s
            if m <= 0:
                n_min = 1
            else:
                n_min = m if m % 2 != 0 else m + 1

            if k * n_min <= n - s:
                return True, (s, k, m, n_min)
    return False, None

